an class=&#34;line&#34;&gt;68&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;69&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;verbose: false&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;debug: false&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;loglevel: critical&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;logpath: log&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;handler_type: re&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;proxy: &amp;quot;&amp;quot; # http://127.0.0.1:7890&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;max_depth: 1 # 0 for no limit&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;max_page_num: 1000 # 0 for no limit&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;timeout: 5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;follow_redirects: true&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;workers_num: 1000&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;headers:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  Accept: &amp;quot;*/*&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  Cookie: &amp;quot;&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  User-Agent: Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/80.0.3987.87 Safari/537.36 SE 2.X MetaSr 1.0&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;urlFind:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - &amp;quot;[\&amp;quot;&amp;#x27;‘“`]\\s&amp;#123;0,6&amp;#125;(https&amp;#123;0,1&amp;#125;:[-a-zA-Z0-9()@:%_\\+.~#?&amp;amp;//=&amp;#123;&amp;#125;]&amp;#123;2,250&amp;#125;?)\\s&amp;#123;0,6&amp;#125;[\&amp;quot;&amp;#x27;‘“`]&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - &amp;quot;=\\s&amp;#123;0,6&amp;#125;(https&amp;#123;0,1&amp;#125;:[-a-zA-Z0-9()@:%_\\+.~#?&amp;amp;//=&amp;#123;&amp;#125;]&amp;#123;2,250&amp;#125;)&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - &amp;quot;[\&amp;quot;&amp;#x27;‘“`]\\s&amp;#123;0,6&amp;#125;([#,.]&amp;#123;0,2&amp;#125;/[-a-zA-Z0-9()@:%_\\+.~#?&amp;amp;//=&amp;#123;&amp;#125;]&amp;#123;2,250&amp;#125;?)\\s&amp;#123;0,6&amp;#125;[\&amp;quot;&amp;#x27;‘“`]&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - &amp;quot;\&amp;quot;([-a-zA-Z0-9()@:%_\\+.~#?&amp;amp;//=&amp;#123;&amp;#125;]+?[/]&amp;#123;1&amp;#125;[-a-zA-Z0-9()@:%_\\+.~#?&amp;amp;//=&amp;#123;&amp;#125;]+?)\&amp;quot;&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - &amp;quot;href\\s&amp;#123;0,6&amp;#125;=\\s&amp;#123;0,6&amp;#125;[\&amp;quot;&amp;#x27;‘“`]&amp;#123;0,1&amp;#125;\\s&amp;#123;0,6&amp;#125;([-a-zA-Z0-9()@:%_\\+.~#?&amp;amp;//=&amp;#123;&amp;#125;]&amp;#123;2,250&amp;#125;)|action\\s&amp;#123;0,6&amp;#125;=\\s&amp;#123;0,6&amp;#125;[\&amp;quot;&amp;#x27;‘“`]&amp;#123;0,1&amp;#125;\\s&amp;#123;0,6&amp;#125;([-a-zA-Z0-9()@:%_\\+.~#?&amp;amp;//=&amp;#123;&amp;#125;]&amp;#123;2,250&amp;#125;)&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;jsFind:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - (https&amp;#123;0,1&amp;#125;:[-a-zA-Z0-9（）@:%_\+.~#?&amp;amp;//=]&amp;#123;2,100&amp;#125;?[-a-zA-Z0-9（）@:%_\+.~#?&amp;amp;//=]&amp;#123;3&amp;#125;[.]js)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - &amp;#x27;[&amp;quot;&amp;#x27;&amp;#x27;‘“`]\s&amp;#123;0,6&amp;#125;(/&amp;#123;0,1&amp;#125;[-a-zA-Z0-9（）@:%_\+.~#?&amp;amp;//=]&amp;#123;2,100&amp;#125;?[-a-zA-Z0-9（）@:%_\+.~#?&amp;amp;//=]&amp;#123;3&amp;#125;[.]js)&amp;#x27;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - =\s&amp;#123;0,6&amp;#125;[&amp;quot;,&amp;#x27;,’,”]&amp;#123;0,1&amp;#125;\s&amp;#123;0,6&amp;#125;(/&amp;#123;0,1&amp;#125;[-a-zA-Z0-9（）@:%_\+.~#?&amp;amp;//=]&amp;#123;2,100&a