[\w/]+?\.js\.map)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loaded: true&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - name: URL as a Value&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    regex: (\b\w+?=(https?)(://|%3a%2f%2f))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loaded: false&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - name: Email&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    regex: &amp;quot;[&amp;#x27;\&amp;quot;]([\\w]+(?:\\.[\\w]+)*@(?:[\\w](?:[\\w-]*[\\w])?\\.)+[\\w](?:[\\w-]*[\\w])?)[&amp;#x27;\&amp;quot;]&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loaded: true&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - name: Internal IP&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    regex: &amp;#x27;[^0-9]((127\.0\.0\.1)|(10\.\d&amp;#123;1,3&amp;#125;\.\d&amp;#123;1,3&amp;#125;\.\d&amp;#123;1,3&amp;#125;)|(172\.((1[6-9])|(2\d)|(3[01]))\.\d&amp;#123;1,3&amp;#125;\.\d&amp;#123;1,3&amp;#125;)|(192\.168\.\d&amp;#123;1,3&amp;#125;\.\d&amp;#123;1,3&amp;#125;))&amp;#x27;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loaded: true&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - name: Cloud Key&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    regex: \b((accesskeyid)|(accesskeysecret)|\b(LTAI[a-z0-9]&amp;#123;12,20&amp;#125;))\b&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loaded: true&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - name: Shiro&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    regex: (=deleteMe|rememberMe=)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loaded: true&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - name: Suspicious API Key&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    regex: &amp;quot;[\&amp;quot;&amp;#x27;][0-9a-zA-Z]&amp;#123;32&amp;#125;[&amp;#x27;\&amp;quot;]&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loaded: true&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  - name: Jwt&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    regex: &amp;quot;[&amp;#x27;\&amp;quot;](ey[A-Za-z0-9_-]&amp;#123;10,&amp;#125;\\.[A-Za-z0-9._-]&amp;#123;10,&amp;#125;|ey[A-Za-z0-9_\\/+-]&amp;#123;10,&amp;#125;\\.[A-Za-z0-9._\\/+-]&amp;#123;10,&amp;#125;)[&amp;#x27;\&amp;quot;]&amp;quot;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    loaded: true&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;figure class=&#34;highlight javascript&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;https&lt;/span&gt;:&lt;span class=&#34;comment&#34;&gt;//github.com/PadishahIII/SecretScrape&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

 &lt;p&gt;Welcome to &lt;a href=&#34;https://hexo.io/&#34;&gt;Hexo&lt;/a&gt;! This is your very first post. Check &lt;a href=&#34;https://hexo.io/docs/&#34;&gt;documentation&lt;/a&gt; for more info. If you get any problems when using Hexo, you can find the answer in &lt;a href=&#34;https://hexo.io/docs/troubleshooting.html&#34;&gt;troubleshooting&lt;/a&gt; or you can ask me on &lt;a href=&#34;https://github.com/hexojs/hexo/issues&#34;&gt;GitHub&lt;/a&gt;.&lt;/p&gt;
&lt;h2 id=&#34;quick-start&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#quick-start&#34;&gt;#&lt;/a&gt; Quick Start&lt;/h2&gt;
&lt;h3 id=&#34;create-a-new-post&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#create-a-new-post&#34;&gt;#&lt;/a&gt; Create a new post&lt;/h3&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;$ hexo new &lt;span class=&#34;string&#34;&gt;&amp;quot;My New Post&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;More info: &lt;a href=&#34;https://hexo.io/docs/writing.html&#34;&gt;Writing&lt;/a&gt;&lt;/p&gt;
&lt;h3 id=&#34;run-server&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#run-server&#34;&gt;#&lt;/a&gt; Run server&lt;/h3&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;$ hexo server&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;More info: &lt;a href=&#34;https://hexo.io/docs/server.html&#34;&gt;Server&lt;/a&gt;&lt;/p&gt;
&lt;h3 id=&#34;generate-static-files&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#generate-static-files&#34;&gt;#&lt;/a&gt; Generate static files&lt;/h3&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;$ hexo generate&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;More info: &lt;a href=&#34;https://hexo.io/docs/generating.html&#34;&gt;Generating&lt;/a&gt;&lt;/p&gt;
&lt;h3 id=&#34;deploy-to-remote-sites&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#deploy-to-remote-sites&#34;&gt;#&lt;/a&gt; Deploy to remote sites&lt;/h3&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;$ hexo deploy&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;More info: &lt;a href=&#34;https://hexo.io/docs/one-command-deployment.html&#34;&gt;Deployment&lt;/a&gt;&lt;/p&gt;

